const CAM_BASE = new THREE.Vector3(3, 8.5, 27);
const CAM_TARGET = new THREE.Vector3(-0.5, 10.5, -60);
camera.position.copy(CAM_BASE);
camera.lookAt(CAM_TARGET);

// ---------- sky ----------
const SUN_DIR = new THREE.Vector3(-0.42, 0.045, -1).normalize();
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide, depthWrite: false, fog: false,
  uniforms: {
    uTop: { value: new THREE.Color(0x30306e) },
    uMid: { value: new THREE.Color(0xd2799f) },
    uHorizon: { value: new THREE.Color(0xf7c4aa) },
    uSun: { value: new THREE.Color(0xffd29a) },
    uSunDir: { value: SUN_DIR },
  },
  vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
  fragmentShader: `
    uniform vec3 uTop, uMid, uHorizon, uSun, uSunDir; varying vec3 vDir;
    void main(){
      vec3 d = normalize(vDir); float h = max(d.y, 0.0);
      vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.16, h));
      col = mix(col, uTop, smoothstep(0.12, 0.65, h));
      float s = max(dot(d, uSunDir), 0.0);
      col += uSun * (pow(s, 400.0) * 2.0 + pow(s, 24.0) * 0.45 + pow(s, 4.0) * 0.12);
      gl_FragColor = vec4(col, 1.0);
      #include <colorspace_fragment>
    }`,
});
const sky = new THREE.Mesh(new THREE.SphereGeometry(900, 32, 16), skyMat);
sky.renderOrder = -10;
scene.add(sky);

